with f as (select n.nspname||'.'||p.proname as fq, regexp_replace(regexp_replace(p.prosrc, '--[^\n]*', '', 'g'), '/\*.*?\*/', '', 'g') as src from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('crm','private','public') and l.lanname in ('sql','plpgsql')), t as (select fq, 'T:'||r[2]||'.'||r[3] as ref from f, regexp_matches(f.src, '\m(from|join|into|update|delete\s+from|truncate|only|lock\s+table)\s+(crm|private|public)\.([a-z0-9_]+)', 'gi') as r), g as (select fq, 'F:'||r[1]||'.'||r[2] as ref from f, regexp_matches(f.src, '\m(crm|private|public)\.([a-z0-9_]+)\s*\(', 'g') as r) select fq, string_agg(distinct ref, ' ') as refs from (select * from t union all select * from g) x group by fq order by fq
